schema_ddl:
CREATE TABLE conti_correnti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    numero_conto TEXT NOT NULL UNIQUE,
    intestatario TEXT NOT NULL,
    saldo_disponibile NUMERIC(15,2) NOT NULL CHECK (saldo_disponibile >= 0)
);

CREATE TABLE transazioni_finanziarie (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    conto_id INT NOT NULL REFERENCES conti_correnti(id) ON DELETE CASCADE,
    importo_transazione NUMERIC(12,2) NOT NULL,
    data_valuta TEXT NOT NULL,
    stato_operazione TEXT NOT NULL CHECK (stato_operazione IN ('COMPLETATA', 'PENDENTE', 'ANNULLATA'))
);

CREATE TABLE categorie_operazione (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_categoria TEXT NOT NULL UNIQUE,
    descrizione_categoria TEXT NOT NULL
);

CREATE TABLE dettagli_transazione (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    transazione_id INT NOT NULL REFERENCES transazioni_finanziarie(id) ON DELETE CASCADE,
    categoria_id INT REFERENCES categorie_operazione(id) ON DELETE SET NULL,
    note_aggiuntive TEXT
);
